import{_t as e,at as t,et as n,n as r,rt as i}from"./chunks/framework.GGfqtSwG.js";var a=JSON.parse(`{"title":"Manifest","description":"","frontmatter":{},"headers":[],"relativePath":"manifest.md","filePath":"manifest.md"}`),o={name:`manifest.md`};function s(r,a,o,s,c,l){return e(),i(`div`,null,[...a[0]||=[n(`h1`,{id:`manifest`,tabindex:`-1`},[t(`Manifest `),n(`a`,{class:`header-anchor`,href:`#manifest`,"aria-label":`Permalink to “Manifest”`},`​`)],-1),n(`p`,null,`Det bliver sværere og sværere at være transperson i Danmark. Vi sidder fast på ventelister i årevis og bliver afvist af CKI uden fornuftig grund. De holder behandling fra os, og der er ingen tegn på, at det bliver bedre foreløbigt. Derfor er det afgørende, at vi finder vores egne måder at få den kønsbekræftende behandling, vi har brug for. Jeg har lavet denne guide, fordi transpersoner fortjener autonomi og adgang til retfærdig og sikker behandling, uanset hvad CKI mener.`,-1),n(`p`,null,`Denne guide kan eventuelt også være brugbar for transpersoner i andre nordiske eller europæiske lande, men den er umiddelbart lavet til danske transpersoner. Jeg skrev den fordi jeg har snakket med mange transpersoner her i Danmark som sidder fast på CKI's ventelister og ikke alle er klar over at der er andre muligheder.`,-1),n(`p`,null,`Da testosteron er vurderet som et dopingmiddel af Lægemiddelstyrelsen, er det ulovligt at besidde uden recept. Så selvom jeg rigtig gerne ville, så kan denne guide derfor ikke dække DIY maskuliniserene hormonbehandling.`,-1),n(`p`,null,[t(`Alt i guiden er skrevet ud fra mine egne oplevelser og ud fra samtaler jeg har haft med andre transpersoner. Jeg har ikke nogen medicinsk uddannelse og guiden kan have fejl. Hvis du finder noget som er forkert eller hvis du har information du vil tilføje, send en mail til `),n(`a`,{href:`mailto:dktransguide@pm.me`,target:`_blank`,rel:`noreferrer`},`dktransguide@pm.me`),t(`.`)],-1)]])}var c=r(o,[[`render`,s]]);export{a as __pageData,c as default};